# Q12 report update: appends the Q12 results to /output/report.json (idempotent: removes earlier Q12 entries), corrects the primary-beam caveat,
# and flags the Q3 round-1 ladder entries (symmetric band-scale nuisance) as superseded by the Q12 recovery numbers.
import json,shutil,os
O='/workspace/out/'; R='/output/report.json'
if not os.path.exists(O+'report_before_q12.json'): shutil.copy(R,O+'report_before_q12.json')
r=json.load(open(O+'report_before_q12.json')); res=r['results']
A=lambda **k:[{'name':a,'value':str(b)} for a,b in k.items()]
ASS=A(distance='40 Mpc',velocity_window='|v-2780|<350 km/s radio-LSRK, per-pixel median baseline from v<-600 and 450<v<600 km/s, pbcor cubes, Jy/beam km/s',
      beams='Gaussian image-plane convolution of the moment-0 maps to circular 1.05/2/3/4.5/6.5/10" beams (flux rescaled by the beam-area ratio, as s26/s30); Xb4f native beam 5.7x3.5" also used',
      errors='rms of 16 sign-flipped line-free pseudo-moment maps pushed through the same convolution; 5% independent flux scale per array added where a ratio is modelled (7% on a ratio)',
      MRS='nominal Band 6 maximum recoverable scales (Cycle-5 handbook values scaled to 265 GHz, assumption): Xb4f 25", Xb4d/Xb4f=0.30 (0.20-0.45), Xb4b/Xb4d=0.40 (0.30-0.55); only ratios enter',
      ACA='Xb4f, Xb47, Xb55 are 7-m (ACA) data sets (noise-map PB FWHM 39/30/58"); MRS scales with wavelength (exponent U[0.5,1.5] for configuration differences)',
      loss_only='true flux = observed/R with R<=1 for each array; relative multipliers R_55/R_4f>=1>=R_47/R_4f follow from MRS~lambda')
def add(q,v,c,e,target,unc,unit=None): res.append(dict(quantity=q,target=target,value=v,uncertainty=unc,unit=unit,assumptions=ASS,confidence=c,evidence=e))
res[:]=[x for x in res if not x['evidence'].startswith('Q12:')]
E=lambda s:'Q12: '+s
add('Which dish are Xb4f, Xb47 and Xb55? Primary-beam FWHM from the pbcor noise maps and the PB gain at each position',
 'pbcor noise ~ 1/PB fitted with a Gaussian: Xb4d 21.9" (12-m expectation 1.13 lambda/D = 21.9"), Xb4b 23.1", Xb4f 39.1" (7-m: 37.6"; 12-m: 21.9"), Xb47 29.6-30.8" (7-m: 28.4"; 12-m: 16.6"), Xb55 58-66" (7-m: 56.9"; 12-m: 33.2"). Xb4f/Xb47/Xb55 are therefore ACA (7-m) data and the 17" Band 7 FWHM (12-m) does not apply. PB gain at the clumps (r from the field centre E1 7.8", E2 6.0", W 7.6"): Xb47 0.83/0.90/0.84, Xb4f 0.89/0.93/0.89, Xb55 0.95/0.97/0.95; N,S,Bridge >=0.98. pbcor correction factor of Xb47 at E1/E2/W is 1.20/1.11/1.19 (a 12-m 17" model would give 1.84/1.43/1.79, which the data exclude). A 10% error in the ACA FWHM changes the Xb47 correction at E1 by 3%.',
 'medium',E('scripts/s56e_extrapolate.py section 5 -> out/q12/extrapolation.txt; s55a_pb_snr.py'),'Band 7, Band 6 and Band 5 image products at E1/E2/W','FWHM +-2" (fit) ; PB gain +-0.03 at the clumps; the identification as ACA rests on the FWHM and on the beam sizes (4.2x2.8", 5.7x3.5", 8.6x6.0" = 1.2 lambda/45 m), not on file metadata','')
add('Relative flux recovery of the nested Band 6 set at common beams, centre positions (HCO+ 3-2, same line, same beam)',
 'Xb4d/Xb4f at 6.5" / 10": N 0.81/0.72, S 0.74/0.68, Bridge 0.80/0.73, S-blue 0.58/0.58. Xb4b/Xb4d at 1.05" / 3" / 6.5" / 10": N 0.98/0.97/0.87/0.77, S 0.92/0.85/0.84/0.77, Bridge 0.88/0.86/0.85/0.78. Xb4b/Xb4f at 10": N 0.55, S 0.53, Bridge 0.57. HCN 3-2: Xb4d/Xb4f at 10" N 0.69, S 0.61, Bridge 0.69; Xb4b/Xb4d at 10" N 0.82, S 0.85, Bridge 0.82. Even the 1" array loses 20-40% of what the 6" ACA array sees at the nuclei, and loss grows with beam size (more extended structure enters the beam).',
 'high',E('scripts/s56a_maps.py, s56b_measure.py, s56d_recovery_model.py -> out/q12/measure.csv, recovery_table.csv'),'N, S, Bridge, S-blue; Xb4b, Xb4d, Xb4f HCO+/HCN 3-2','statistical 0.005-0.02; adopted +-0.05-0.07 per ratio (5% scale per array); beam convolution assumes Gaussian beams (header beam, channel beams not used)','ratio')
add('Relative flux recovery at the disk clumps E1, E2, W is not a multiplicative factor: Xb4b and Xb4d fluxes are contaminated by the negative bowl of the nuclei',
 'Xb4d/Xb4f (HCO+) at 10" / 6.5": E1 0.65/0.62, E2 0.55/0.33, W 0.63/0.48. HCN: E1 0.62/0.24, E2 0.46/-0.29, W 0.44/0.05. Xb4b/Xb4d HCO+ at 1.05" is 0.93-1.04 (clumps fully recovered when the beam matches the clump size) but 0.64/0.26 at 3" (E1/W) and <=0.35 at >=4.5" (E2/W negative). Xb4b HCN at the clumps is <=0 for beams >=3". A position flux in a smoothed array map at a clump therefore mixes the clump with minus the smooth flux of the nuclei; its ratio to Xb4f is bowl-dominated and can be <=0. Only the 10" Xb4d/Xb4f ratios (0.44-0.65) are interpretable and they are an upper limit on a clump-intrinsic recovery.',
 'medium',E('out/q12/recovery_table.csv, scripts/s56d_recovery_model.py section 1'),'E1, E2, W (HCN/HCO+ 3-2)','ratios +-0.05; 6.5" HCN values at E2/W are noise-comparable (clump flux 0.6-1.9 Jy km/s/beam)','ratio')
add('Aperture curves of growth (r<4/8/12" about the N-S midpoint, 6.5" beam): Xb4d/Xb4f and Xb4b/Xb4f',
 'HCO+: Xb4d/Xb4f 0.81/0.65/0.50 and Xb4b/Xb4f 0.69/0.47/-0.01 at r<4/8/12" (Xb4f flux 51.6/94.2/93.7 Jy km/s). HCN: Xb4d/Xb4f 0.79/0.58/0.37, Xb4b/Xb4f 0.67/0.44/-0.28. Xb4f itself has a bowl: the Xb4f HCO+ aperture sum peaks at 94 Jy km/s (r=10") and falls to 76 at r=18"; mean map value -1.0 to -1.6 Jy/beam km/s (3% of the peak) at r=12-18". The ACA array therefore also resolves out extended flux and Xb4f is not a 100% recovery reference.',
 'high',E('out/q12/growth.csv; out/s26_recovery.txt (r<4/8/12)'),'aperture sums around N-S midpoint','+-0.03 (noise), bowl sign verified in Xb4f, Xb4d, Xb4b','Jy km/s')
add('Retained flux as a power law of the maximum recoverable scale, F ~ MRS^alpha, from Xb4d/Xb4f (10" beam), centre vs disk',
 'alpha_df (HCO+ / HCN): N 0.27[0.20,0.36]/0.31[0.23,0.41], S 0.32[0.25,0.43]/0.41[0.32,0.54], Bridge 0.27/0.32; disk E1 0.35[0.27,0.47]/0.39, E2 0.50[0.39,0.65]/0.65[0.52,0.85], W 0.39[0.30,0.51]/0.68[0.55,0.88]. At N, S, Bridge the Xb4b/Xb4d slope agrees with the Xb4d/Xb4f slope (HCO+ 10": 0.29/0.27, 0.28/0.32, 0.27/0.27), which supports using the nominal MRS ratios and one power law over MRS=3-25"; at the clumps the Xb4b/Xb4d slope is >1 (curve steepens below 7") so alpha_df is the local slope nearest the ACA scale. alpha is smaller at 6.5" (N 0.17) than at 10". Disk slopes are 1.3-2.5x the centre slopes: the disk loses more as the scale shrinks.',
 'medium',E('scripts/s56d_recovery_model.py section 2a, s56e_extrapolate.py section 1 -> out/q12/recovery_model.txt, extrapolation.txt'),'N,S,Bridge,E1,E2,W; HCO+ and HCN','median [16,84] from MC over 7% ratio error and MRS_d/MRS_f in 0.20-0.45 (which scales alpha by 0.75-1.5)','dimensionless')
add('Three-point saturating-loss model R(MRS)=1/(1+(s/MRS)^beta) per position (Xb4b, Xb4d, Xb4f): absolute Xb4f recovery',
 'Solutions exist in only 26-100% of the MC draws and are weak: R(Xb4f, 10") HCO+ N 0.74[0.42,0.91], S 0.66[0.33,0.85], Bridge 0.73[0.38,0.91], ap8 0.78[0.51,0.91]; HCN N 0.61[0.27,0.85], ap8 0.69[0.37,0.87]. At E1/E2/W no sensible solution (Xb4b <=0 or beta>2 with R(Xb4f)->1, an artefact of the bowl). Consistent with, but not better than, the outer-scale estimate R_4f=0.64-0.79 (HCO+, MRS_out 40-100") given in the next entry. The absolute Xb4f loss is not measurable from the nested set.',
 'low',E('scripts/s56d_recovery_model.py section 2b -> out/q12/recovery_model.txt/json'),'centre positions','68% intervals as listed','R')
add('Loss-only extrapolation of the recovery to Xb55 (J=2-1) and Xb47 (J=4-3), relative to Xb4f (J=3-2), at the 10" beam',
 'R_55/R_4f (>=1) and R_47/R_4f (<=1), median [16,84]: HCO+ N 1.06[1.02,1.13]/0.98[0.95,0.99], S 1.07/0.97, Bridge 1.06/0.98, E1 1.09[1.03,1.19]/0.97, E2 1.12[1.04,1.26]/0.95, W 1.09[1.03,1.20]/0.96; HCN N 1.07[1.02,1.15]/0.97, S 1.10[1.03,1.21]/0.96, E2 1.16[1.05,1.35]/0.94, W 1.17[1.05,1.37]/0.94. Separate centre/disk alphas are used. Absolute recovery of Xb4f (model dependent, outer scale 40-100"): R_4f 0.69-0.79 centre, 0.64-0.72 HCO+ disk, 0.53-0.70 HCN disk (so absolute column/mass lower limits are 1.3-1.9x low; this common factor cancels in every ratio). Band 5 can recover MORE than Xb4f (longer wavelength = larger MRS for the same 7-m baselines), Band 7 less.',
 'low',E('scripts/s56e_extrapolate.py section 2 -> out/q12/extrapolation.txt'),'N,S,Bridge,E1,E2,W','MC over alpha, MRS ratio (0.2-0.45), MRS exponent U[0.5,1.5], saturation U[0,1], J-structure kJ U[1,1.5] (2-1) / U[0.5,1] (4-3); stress corner (alpha 84%, no saturation, kJ=3): R_55/R_4f up to 2.0-2.7 at the centre','multiplier')
add('Brightness-temperature ladder ratios at 10" before and after the one-sided recovery correction',
 'T(2-1)/T(3-2) observed -> corrected (median [16,84], 10% calibration per band included): HCO+ N 2.02->1.89[1.62,2.19], S 2.10->1.93, Bridge 2.03->1.89, E1 2.38->2.16, E2 2.27->2.00, W 2.72->2.44; HCN N 2.57->2.38[2.04,2.77], S 2.74->2.46, Bridge 2.62->2.40, E1 3.75->3.39, E2 3.59->3.06, W 4.08->3.43. T(4-3)/T(3-2): HCO+ N 0.45->0.46, E1 0.34->0.36, W 0.29->0.30; HCN N 0.34->0.35, E1 0.16->0.17, E2 0.20->0.21 (HCN W 0.04, 4-3 not detected). The correction lowers T21/T32 by 4-16% (more at the disk) and raises T43/T32 by 2-6%. Stress corner: T21/T32 stays >=0.95-1.2 at the centre (HCN N 1.20, S 1.01; HCO+ N 1.03, S 0.95) but could fall below 1 at E2/W (0.7-0.8); T43/T32 stays <=0.56 everywhere (HCO+) and <=0.45 centre (HCN).',
 'medium',E('scripts/s56e_extrapolate.py sections 3 and 7'),'N,S,Bridge,E1,E2,W; HCN and HCO+','see text; ratios are dominated by the 10% per-band calibration (+-0.3 on T21/T32 at N)','K ratio')
add('Disk/centre contrast of the ladder ratios after recovery correction',
 'Disk/N of T(2-1)/T(3-2): HCN E1 1.45->1.43[1.14,1.78], E2 1.40->1.27[1.00,1.62], W 1.58->1.43[1.11,1.84]; HCO+ E1 1.18->1.15[0.92,1.44], E2 1.12->1.06[0.84,1.33], W 1.35->1.30[1.04,1.62]. Disk/N of T(4-3)/T(3-2): HCN E1 0.48->0.49, E2 0.59->0.62, W 0.12->0.13; HCO+ E1 0.76->0.77, E2 0.78->0.80, W 0.64->0.65. The disk 4-3/3-2 deficit relative to N survives (0.5-0.8 for HCO+, 0.12-0.6 for HCN; independent of recovery within 5%). The disk excess of 2-1/3-2 is 1-1.5 sigma-marginal for HCN (1.3-1.4) and consistent with 1 for HCO+ E1/E2 once recovery is free.',
 'medium',E('scripts/s56e_extrapolate.py section 6'),'E1,E2,W vs N','recovery draws independent per position (shared systematics not propagated: contrast errors slightly overestimated)','ratio of ratios')
add('Sensitivity of the same-J HCN/HCO+ ratio (Xb4f 3-2) to differential HCN vs HCO+ loss',
 'delta alpha = alpha_HCN - alpha_HCO+ : N 0.04[-0.08,0.16], S 0.09[-0.05,0.24], Bridge 0.05, E1 0.04, E2 0.15[-0.03,0.37], W 0.29[0.12,0.50]. True/observed HCN/HCO+ at Xb4f (outer scale 40-100"): N 1.03[0.93,1.15], S 1.08[0.96,1.24], Bridge 1.04, E1 1.03, E2 1.14[0.97,1.40], W 1.29[1.10,1.61]. Observed Xb4d/Xb4f ratio change of HCN/HCO+ at 10": N 0.96, S 0.89, Bridge 0.95, i.e. the N/S/Bridge ratios (p0005) are robust to recovery at the <=10% level; the W clump ratio could be raised by up to ~30% (HCN is the more extended line there), the disk HCN/HCO+ remains low (observed 0.14 at 4-3, 0.34 at 3-2, 0.52 at 2-1).',
 'medium',E('scripts/s56e_extrapolate.py section 4; out/q12/recovery_table.csv'),'same-J ratio','as listed','factor')
add('Global Fourier-filter model of the nested set (negative result)',
 'Fitting Xb4d and Xb4b maps as Xb4f times a smooth uv-hole transfer ratio T_d/T_f, T_b/T_f (T=1-exp(-(q/q_a)^p), p=1,2,4, Xb4f hole 6-16 m, free flux scales) fails: chi2_red 25-72 over 13014 pixels, with the flux scales and p at their bounds, and the Xb4b-from-Xb4d prediction at 2-3" overshoots the N peak by 1.6x. The images are not linear-filter copies of one another: clean-model effects, the positive annulus at r=14-16" in Xb4d/Xb4b (+2 Jy/beam km/s) and bowl structure beyond the 19" crop are not captured. A per-position recovery from such a model would be unreliable; the empirical ratios and slopes above are used instead.',
 'high',E('scripts/s56c_transfer_fit.py -> out/q12/transfer_fit.txt'),'whole maps, r<15"','chi2_red 25-72','')
res[:]=[x for x in res]
# ---- flag Q3 round-1 entries
for x in res:
    if x['evidence'].startswith('Q3:') and 'Q12 NOTE' not in x['uncertainty']:
        x['uncertainty']=str(x['uncertainty'])+' | Q12 NOTE: these Q3 round-1 numbers used a symmetric band-scale nuisance (20/10/20%) common to all regions and the 12-m PB assumption; Q12 shows the recovery loss is one-sided (R_55>=R_4f>=R_47, ~4-16% on T21/T32, <=6% on T43/T32 within the model range), larger at the disk, and that Xb4f/Xb47/Xb55 are ACA (PB gain 0.83-0.97 at the clumps). Treat Q3 n,Tk intervals at the disk as provisional until refit with the Q12 priors.'
# ---- correct the PB caveat
r['caveats']=[c.replace('a 12 m Gaussian primary-beam term (5-10% for pb<0.9)','a Gaussian primary-beam term (5-10% for pb<0.9; NOTE Q12: Xb4f, Xb47 and Xb55 are 7-m ACA data with PB FWHM 39/30/58", so the 12-m 1.13 lambda/D FWHM originally assumed is wrong for them; gains in out/q12 pb table)') for c in r['caveats']]
r['caveats'].append('Q12: the nested-set recovery is relative to Xb4f; the absolute loss of the ACA data (and of every array) is not measurable without short-spacing/total-power data: absolute fluxes, column densities and masses are lower limits (R_4f ~0.5-0.8 in the outer-scale model, model dependent). Maximum recoverable scales are assumed from nominal configuration values (only ratios enter; slopes at N,S,Bridge agree between Xb4b/Xb4d and Xb4d/Xb4f). At the disk clumps array-map fluxes are contaminated by the negative bowl of the nuclei, so per-position recoveries there are bounds, not factors.')
r['interpretation']=r['interpretation']+' | Q12: the three low-resolution sets (Xb55, Xb4f, Xb47) are ACA data; losses relative to Xb4f are small (R_55/R_4f 1.06-1.17, R_47/R_4f 0.94-0.98) so cross-band ladder ratios change by 4-16% (T21/T32) and 2-6% (T43/T32), which does not remove the T(2-1)>T(3-2) excess or the strongly sub-thermal T(4-3)/T(3-2) (0.04-0.46). The same-J HCN/HCO+ ratios at N, S, Bridge are robust to recovery at the <=10% level. The disk (E1,E2,W) recovery is poorly constrained (the 1" and 0.25" arrays keep 0-65%).'
json.dump(r,open(R,'w'),indent=1)
